                    b.Property<long>("BoardRank")
                        .HasColumnType("bigint")
                        .HasColumnName("board_rank")
                        .HasComment("O lugar do card na coluna do quadro; o menor fica em cima. So se compara dentro da mesma coluna. Com folga entre vizinhos: por um card entre dois escolhe um numero no meio, e a coluna e renumerada quando a folga acaba.");

                    b.Property<DateTime>("CreatedAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("created_at")
                        .HasComment("Criacao do registro, em UTC.");

                    b.Property<long?>("CreatedByUserId")
                        .HasColumnType("bigint")
                        .HasColumnName("created_by_user_id")
                        .HasComment("Quem do time criou o card. Nulo no relato: quem escreveu nao tem usuario aqui.");

                    b.Property<DateTime?>("DeletedAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("deleted_at")
                        .HasComment("Nulo enquanto o registro vale; preenchido no lugar de apagar.");

                    b.Property<string>("Description")
                        .HasMaxLength(10000)
                        .HasColumnType("character varying(10000)")
                        .HasColumnName("description")
                        .HasComment("Descricao do card do time, em Markdown; o painel a desenha sem HTML. Sempre nula no relato, cujo texto e de quem relatou.");

                    b.Property<DateOnly?>("DueDate")
                        .HasColumnType("date")
                        .HasColumnName("due_date")
                        .HasComment("O prazo: so a data, sem hora. Nulo e sem prazo. Interno.");

                    b.Property<string>("Kind")
                        .IsRequired()
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("kind")
                        .HasComment("report | team. O relato veio de fora, pela ferramenta; o card do time nasceu no painel e nunca tem lado de fora.");

                    b.Property<DateTime?>("ModeratedAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("moderated_at")
                        .HasComment("Quando alguem do time decidiu. Nulo enquanto ninguem decidiu.");

                    b.Property<long?>("ModeratedByUserId")
                        .HasColumnType("bigint")
                        .HasColumnName("moderated_by_user_id")
                        .HasComment("Quem do time decidiu. Nulo enquanto ninguem decidiu, e tambem quando a conta de quem decidiu foi esvaziada. Nunca sai em rota publica.");

                    b.Property<string>("ModerationState")
                        .IsRequired()
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("moderation_state")
                        .HasComment("pending, approved ou rejected. Todo relato nasce pending, inclusive em projeto privado: e o que faz marcar o projeto como publico depois nao publicar o historico inteiro de uma vez.");

                    b.Property<int>("Number")
                        .HasColumnType("integer")
                        .HasColumnName("number")
                        .HasComment("O numero curto do card no projeto (#42). Interno: nenhuma rota publica o devolve. Vem de projects.last_card_number; pode pular, nunca repete.");

                    b.Property<string>("Origin")
                        .HasMaxLength(260)
                        .HasColumnType("character varying(260)")
                        .HasColumnName("origin")
                        .HasComment("Dominio informado pela pagina que embutiu a ferramenta. Indicio, nunca prova.");

                    b.Property<long?>("ParentReportId")
                        .HasColumnType("bigint")
                        .HasColumnName("parent_report_id")
                        .HasComment("O card de que este e subtarefa; nulo no card que nao e subtarefa. So o card do time e subtarefa, e um nivel so (o servico confere). Interno.");

                    b.Property<long?>("PriorityId")
                        .HasColumnType("bigint")
                        .HasColumnName("priority_id")
                        .HasComment("A prioridade do projeto que o time escolheu. Nulo e sem prioridade, e e como o card nasce. Interno.");

                    b.Property<long>("ProjectId")
                        .HasColumnType("bigint")
                        .HasColumnName("project_id")
                        .HasComment("Projeto de onde o relato veio, resolvido pela chave publica da requisicao.");

                    b.Property<long?>("ProjectPublicStageId")
                        .HasColumnType("bigint")
                        .HasColumnName("project_public_stage_id")
                        .HasComment("Em que etapa da jornada publica o relato aparece. Nulo enquanto ele nao apareceu em nenhuma. E cache, como project_state_id: a verdade e a sequencia de eventos.");

                    b.Property<long?>("ProjectStateId")
                        .HasColumnType("bigint")
                        .HasColumnName("project_state_id")
                        .HasComment("Onde o relato esta na fila do projeto. Nulo quando o projeto ainda nao tem estado nenhum. E cache: a verdade e a sequencia de eventos.");

                    b.Property<Guid>("PublicId")
                        .HasColumnType("uuid")
                        .HasColumnName("public_id")
                        .HasComment("Identificador publico, GUID aleatorio. E o que aparece em URL e API.");

                    b.Property<DateTime?>("PublicStageDueAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("public_stage_due_at")
                        .HasComment("Quando a ultima mudanca de etapa publica passa a valer para quem relatou. Preenchida e a janela para desfazer; nula e o estado normal. E ela que sobrevive, e nao a mensagem na fila.");

                    b.Property<long?>("ReporterCodeId")
                        .HasColumnType("bigint")
                        .HasColumnName("reporter_code_id")
                        .HasComment("Codigo pessoal de quem escreveu, quando o projeto usa esse modo. Nulo no modo protocolo e nos relatos anteriores ao modo existir — e esses continuam valendo pelo link.");

                    b.Property<string>("ReporterName")
                        .HasMaxLength(80)
                        .HasColumnType("character varying(80)")
                        .HasColumnName("reporter_name")
                        .HasComment("Nome de quem relatou, quando o projeto pede e a pessoa quis dar. Nulo e o normal. Interno por padrao: so aparece la fora com o projeto em publico identificado E reporter_name_is_public verdadeiro.");

                    b.Property<bool>("ReporterNameIsPublic")
                        .HasColumnType("boolean")
                        .HasColumnName("reporter_name_is_public")
                        .HasComment("Quem relatou escolheu assinar o relato. Falso por padrao — a caixa nasce desmarcada, porque o que esta em jogo e o nome dela ao lado de um texto que qualquer um le.");

                    b.Property<string>("ReporterTitle")
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)")
                        .HasColumnName("reporter_title")
                        .HasComment("O titulo que a pessoa escreveu na ferramenta. Nunca muda, e e o unico titulo que volta para ela. Nulo quando ela nao respondeu, e sempre no card do time.");

                    b.Property<string>("Route")
                        .HasMaxLength(500)
                        .HasColumnType("character varying(500)")
                        .HasColumnName("route")
                        .HasComment("So o caminho da pagina, sem query e sem fragmento: e na query que viaja dado sensivel.");

                    b.Property<DateTime>("StateChangedAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("state_changed_at")
                        .HasComment("Quando o card entrou na coluna em que esta, ou voltou a ela (reaberto, ou desarquivado por quem relatou), em UTC. A ultima coluna do quadro mostra so o que entrou nela nos ultimos dias do projeto.");

                    b.Property<string>("Text")
                        .HasMaxLength(5000)
                        .HasColumnType("character varying(5000)")
                        .HasColumnName("text")
                        .HasComment("O relato como a pessoa escreveu. Nulo no card do time, que tem titulo e descricao.");

                    b.Property<string>("Title")
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)")
                        .HasColumnName("title")
                        .HasComment("Titulo do time. Obrigatorio no card do time; no relato, o que o time reescreveu, nulo ate alguem reescrever. Interno: nenhuma rota publica o devolve.");

                    b.Property<string>("TrackingCode")
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("tracking_code")
                        .HasComment("O protocolo que a pessoa le e repete. Alfabeto sem 0, O, 1 e I; colisao tratada na geracao. Nulo no card do time, que nao tem lado de fora.");

                    b.Property<string>("Type")
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("type")
                        .HasComment("bug | improvement | question. Lista fixa por enquanto. Nulo no card do time.");

                    b.Property<DateTime>("UpdatedAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("updated_at")
                        .HasComment("Ultima alteracao, em UTC.");

                    b.HasKey("Id")
                        .HasName("pk_reports");

                    b.HasIndex("AccessTokenHash")
                        .HasDatabaseName("ix_reports_access_token_hash");

                    b.HasIndex("AssigneeUserId")
                        .HasDatabaseName("ix_reports_assignee_user_id");

                    b.HasIndex("CreatedByUserId")
                        .HasDatabaseName("ix_reports_created_by_user_id");

                    b.HasIndex("DeletedAt")
                        .HasDatabaseName("ix_reports_deleted_at");

                    b.HasIndex("ModeratedByUserId")
                        .HasDatabaseName("ix_reports_moderated_by_user_id");

                    b.HasIndex("ParentReportId")
                        .HasDatabaseName("ix_reports_parent_report_id");

                    b.HasIndex("PriorityId")
                        .HasDatabaseName("ix_reports_priority_id");

                    b.HasIndex("ProjectPublicStageId")
                        .HasDatabaseName("ix_reports_project_public_stage_id");

                    b.HasIndex("ProjectStateId")
                        .HasDatabaseName("ix_reports_project_state_id");

                    b.HasIndex("PublicId")
                        .IsUnique()
                        .HasDatabaseName("ux_reports_public_id");

                    b.HasIndex("PublicStageDueAt")
                        .HasDatabaseName("ix_reports_public_stage_due_at")
                        .HasFilter("public_stage_due_at IS NOT NULL");

                    b.HasIndex("ReporterCodeId")
                        .HasDatabaseName("ix_reports_reporter_code_id");

                    b.HasIndex("TrackingCode")
                        .IsUnique()
                        .HasDatabaseName("ux_reports_tracking_code");

                    b.HasIndex("AccountId", "CreatedAt")
                        .HasDatabaseName("ix_reports_account_id_created_at");

                    b.HasIndex("ProjectId", "CreatedAt")
                        .HasDatabaseName("ix_reports_project_id_created_at");

                    b.HasIndex("ProjectId", "ModerationState")
                        .HasDatabaseName("ix_reports_project_id_moderation_state");

                    b.HasIndex("ProjectId", "Number")
                        .IsUnique()
                        .HasDatabaseName("ux_reports_project_id_number");

                    b.HasIndex("ProjectId", "ProjectStateId", "BoardRank")
                        .HasDatabaseName("ix_reports_project_id_project_state_id_board_rank");

                    b.ToTable("reports", null, t =>
                        {
                            t.HasComment("Os cards do trabalho do time: o relato que a pessoa de fora escreveu (kind = report) e o card que o time criou no painel (kind = team). O relato e a primeira tabela do sistema que nasce sem conta e sem sessao, e por isso carrega o proprio account_id, o protocolo que a pessoa le e o hash do token que abre o acompanhamento; o card do time nao tem lado de fora nenhum.");

                            t.HasCheckConstraint("ck_reports_kind", "kind IN ('report', 'team')");

                            t.HasCheckConstraint("ck_reports_number", "number > 0");

                            t.HasCheckConstraint("ck_reports_parent_not_self", "parent_report_id IS NULL OR parent_report_id <> id");

                            t.HasCheckConstraint("ck_reports_parent_team", "parent_report_id IS NULL OR kind = 'team'");

                            t.HasCheckConstraint("ck_reports_report_fields", "kind <> 'report' OR (tracking_code IS NOT NULL AND access_token_hash IS NOT NULL AND type IS NOT NULL AND text IS NOT NULL AND description IS NULL)");

                            t.HasCheckConstraint("ck_reports_team_fields", "kind <> 'team' OR (title IS NOT NULL AND tracking_code IS NULL AND access_token_hash IS NULL AND reporter_code_id IS NULL AND project_public_stage_id IS NULL AND public_stage_due_at IS NULL AND moderation_state = 'pending' AND type IS NULL AND text IS NULL AND reporter_title IS NULL)");
                        });
                });

            modelBuilder.Entity("Pds.Domain.Entities.ReportAttachment", b =>
                {
                    b.Property<long>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("bigint")
                        .HasColumnName("id")
                        .HasComment("Chave interna, sequencial. Nunca sai da aplicacao.");

                    NpgsqlPropertyBuilderExtensions.UseIdentityByDefaultColumn(b.Property<long>("Id"));

                    b.Property<DateTime?>("ConfirmedAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("confirmed_at")
                        .HasComment("Quando a nossa API prendeu o anexo ao relato. Nulo enquanto pendente.");

                    b.Property<string>("ContentType")
                        .IsRequired()
                        .HasMaxLength(100)
                        .HasColumnType("character varying(100)")
                        .HasColumnName("content_type")
                        .HasComment("O tipo declarado, que entrou na assinatura do envio. Garante o rotulo, e nao o conteudo — quem confere os bytes e a confirmacao, na nossa API.");

                    b.Property<DateTime>("CreatedAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("created_at")
                        .HasComment("Criacao do registro, em UTC.");

                    b.Property<DateTime?>("DeletedAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("deleted_at")
                        .HasComment("Nulo enquanto o registro vale; preenchido no lugar de apagar.");

                    b.Property<int>("DisplayOrder")
                        .HasColumnType("integer")
                        .HasColumnName("display_order")
                        .HasComment("A posicao no envio, a partir de zero, dentro da categoria: a ordem em que a pessoa montou as imagens, e a dos arquivos. Guardada, e nao deduzida da hora de chegada — o arquivo tentado de novo chega depois dos outros. Vale dentro de um envio; a hora de chegada desempata.");

                    b.Property<string>("DisplaySize")
                        .IsRequired()
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("display_size")
                        .HasComment("Em que tamanho a imagem aparece logo abaixo do texto: small (um terco da linha), medium (meia), large (tres quartos) ou full (a linha inteira). Fracao da largura do texto, e nao pixels, para o relato montado no quadro aparecer do mesmo jeito no painel e no acompanhamento. Escolha de quem relata; nao muda depois do envio.");

                    b.Property<int?>("DurationSeconds")
                        .HasColumnType("integer")
                        .HasColumnName("duration_seconds")
                        .HasComment("Duracao em segundos, so dos videos antigos.");

                    b.Property<string>("Kind")
                        .IsRequired()
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("kind")
                        .HasComment("image, file ou video (este, so dos anexos antigos). A mesma lista de project_media_kinds, porque e ela que diz qual limite se aplica.");

                    b.Property<string>("ObjectKey")
                        .IsRequired()
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)")
                        .HasColumnName("object_key")
                        .HasComment("O nome do arquivo no armazenamento, sorteado por nos e nunca derivado do nome que veio de fora — nome escolhido de fora permitiria escrever por cima do arquivo de outra pessoa. Nunca um endereco assinado: guardado, ele viraria link permanente com outro nome.");

                    b.Property<string>("OriginalName")
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)")
                        .HasColumnName("original_name")
                        .HasComment("O nome que o arquivo tinha na maquina de quem relata. Guardado para o time, e nunca mostrado do lado de fora: nome de arquivo conta pasta, cliente e numero de contrato, que a imagem nao conta.");

                    b.Property<long?>("PublicCommentId")
                        .HasColumnType("bigint")
                        .HasColumnName("public_comment_id")
                        .HasComment("Preenchido quando o anexo veio junto de uma resposta ao pedido de informacao. Nulo na criacao e na reabertura.");

                    b.Property<Guid>("PublicId")
                        .HasColumnType("uuid")
                        .HasColumnName("public_id")
                        .HasComment("Identificador publico, GUID aleatorio. E o que aparece em URL e API.");

                    b.Property<long?>("ReopenedClosureId")
                        .HasColumnType("bigint")
                        .HasColumnName("reopened_closure_id")
                        .HasComment("Preenchido quando o anexo veio junto de uma reabertura: o fechamento que quem relatou reabriu. Nulo na criacao e na resposta. Coluna propria, e nao deduzida pela data: e ela que faz a cota da reabertura ser um filtro, e a tela saber onde mostrar o arquivo.");

                    b.Property<long>("ReportId")
                        .HasColumnType("bigint")
                        .HasColumnName("report_id")
                        .HasComment("Relato a que o anexo pertence. Obrigatorio mesmo quando o anexo veio numa resposta, para achar o relato ser sempre um salto so — e para o isolamento por projeto nao depender de uma coluna que pode ser nula.");

                    b.Property<long>("SizeBytes")
                        .HasColumnType("bigint")
                        .HasColumnName("size_bytes")
                        .HasComment("Tamanho do que o armazenamento aceitou, lido dele na confirmacao e nao do que o navegador disse.");

                    b.Property<string>("Status")
                        .IsRequired()
                        .HasMaxLength(20)
                        .HasColumnType("character varying(20)")
                        .HasColumnName("status")
                        .HasComment("pending ou confirmed. Nasce pending quando a permissao e assinada, e so vira confirmed quando a nossa API confere os bytes e prende o anexo ao relato. O que fica pending e permissao nao usada: nao aparece nem conta no limite, e o arquivo, se chegou, fica na pasta de envio, que o armazenamento esvazia sozinho.");

                    b.Property<string>("ThumbnailObjectKey")
                        .HasMaxLength(200)
                        .HasColumnType("character varying(200)")
                        .HasColumnName("thumbnail_object_key")
                        .HasComment("A miniatura da imagem, gerada no proprio navegador antes do envio — WebP, ou JPEG onde o navegador nao codifica WebP. Vem de fora, entao ela tambem e conferida. O arquivo nao tem; nos videos antigos, e o quadro de capa.");

                    b.Property<DateTime>("UpdatedAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("updated_at")
                        .HasComment("Ultima alteracao, em UTC.");

                    b.HasKey("Id")
                        .HasName("pk_report_attachments");

                    b.HasIndex("DeletedAt")
                        .HasDatabaseName("ix_report_attachments_deleted_at");

                    b.HasIndex("ObjectKey")
                        .IsUnique()
                        .HasDatabaseName("ux_report_attachments_object_key")
                        .HasFilter("deleted_at IS NULL");

                    b.HasIndex("PublicCommentId")
                        .HasDatabaseName("ix_report_attachments_public_comment_id");

                    b.HasIndex("PublicId")
                        .IsUnique()
                        .HasDatabaseName("ux_report_attachments_public_id");

                    b.HasIndex("ReopenedClosureId")
                        .HasDatabaseName("ix_report_attachments_reopened_closure_id");

                    b.HasIndex("ReportId")
                        .HasDatabaseName("ix_report_attachments_report_id");

                    b.ToTable("report_attachments", null, t =>
                        {
                            t.HasComment("O registro de um arquivo que veio com o relato, com uma resposta ou com uma reabertura. O arquivo em si nao esta aqui e nunca estara: o que a linha guarda e o nome dele no armazenamento, o bastante para pedir uma permissao de leitura quando alguem que pode ver aparecer.");

                            t.HasCheckConstraint("ck_report_attachments_one_submission", "public_comment_id IS NULL OR reopened_closure_id IS NULL");
                        });
                });

            modelBuilder.Entity("Pds.Domain.Entities.ReportClosure", b =>
                {
                    b.Property<long>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("bigint")
                        .HasColumnName("id")
                        .HasComment("Chave interna, sequencial. Nunca sai da aplicacao.");

                    NpgsqlPropertyBuilderExtensions.UseIdentityByDefaultColumn(b.Property<long>("Id"));

                    b.Property<DateTime>("ClosedAt")
                        .HasColumnType("timestamp without time zone")
                        .HasColumnName("closed_at")
